  color: white;
  font-size: 20px;
  text-align: center;
  line-height: 100%;
  cursor: pointer;
  z-index: 10;
  pointer-events: auto; /* Allow interaction with the label */
}

.switch-container label:before {
  content: "";
  position: absolute;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.5);
  opacity: 0;
  transition: opacity 0.3s ease-out;
}

.switch-container input[type="checkbox"]:checked ~ label:before {
  opacity: 1;
}
```

